import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem106 qualifica alegações sem alterar dados operacionais',()=>{for(const [n,titulo,expected] of [["5626051922","Mouse Gamer Titorion Sem Fio Com Sensor Pixart 3311 E 12000 Dpi","Mouse sem fio Titorion — 12.000 DPI anunciados"],["5751316838","Notebook Asus Vivobook 15 X1504va Intel Core I5 1334u 8gb Ram 512gb Ssd Intel Iris Xe Windows 11 Home Tela 15,6 Fhd Silver - Nj1740w","Asus Vivobook 15 X1504VA-NJ1740W — Core i5, 8 GB e SSD de 512 GB"],["5769733060","Notebook Positivo Vision C15M Intel Celeron N4500 Windows 11 Home 4GB RAM 128GB eMMC Tela 15\" Full HD IPS Antirreflexo - Minitela e Tecla Copilot - Cinza","Positivo Vision C15M — Celeron N4500, 4 GB e 128 GB eMMC"]]){const p={id:'mlMLB'+n,titulo,link:'https://produto.mercadolivre.com.br/MLB-'+n,comentario:'anterior',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,link:'https://produto.mercadolivre.com.br/MLB-123'}).comentario,p.comentario);}});
